// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public {
        c = new PRIVATE_ETH_CELL();
        FakeLog log = new FakeLog();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();
    }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        assertTrue(c.balances(actor) == amount);
    }
}

contract FakeLog {
    function AddMessage(address, uint, string calldata) external pure {}
}
